presets.customCss:
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141288ba.webp') no-repeat center center / cover !important;
  z-index: -999 !important;
  pointer-events: none;
}

.xs-panel {
  --xs-bg: transparent; 
  --xs-tile-bg: #000000; 
  --xs-text: #FFFFFF; 
  --xs-muted: #BBBBBB; 
  --xs-accent: #FFFFFF;
  --xs-border: #FFFFFF; 
  --xs-cap: #FFFFFF;
  --xs-action-bg: #000000;
  --xs-done-bg: #000000;

  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;

  width: 100% !important;
  max-width: 100% !important;
  margin: 0 auto !important; 
  padding: 20px 16px !important; 
  border-radius: 0px !important;
}

.xs-frame {
  width: 100% !important;
  max-width: 100% !important;
}

/* 锁定所有卡片为纯黑背景 */
.xs-tile {
  background: #000000 !important;
  border: 1px solid #FFFFFF !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 重点针对暗涌：去掉半透明，强制纯白字 */
.xs-tile-deep {
  opacity: 1 !important;
  background: #000000 !important;
}

.xs-tile-deep .xs-tile-v,
.xs-tile-deep .xs-tile-k,
.xs-tile .xs-tile-v,
.xs-tile .xs-tile-k {
  color: #FFFFFF !important;
}

/* 顶部三个按钮锁定纯黑 */
.xs-action {
  background: #000000 !important;
  border: 1px solid #FFFFFF !important;
  color: #FFFFFF !important;
}

.xs-history {
  background: #000000 !important;
  border: 1px solid #FFFFFF !important;
}

.xs-history-item {
  background: transparent !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important;
}
